scwin.btn_Excel_onclick = function() {
    var today = $c.ut.cGetToday("yyyymmddhhmmss");
    //파일형식 today_화면명.xls
    var xls_path = $c.session.getExcelDownPath() + today + "_ELW공지사항.xls";
    $c.data.downloadGridViewOffice(grd_ELW_List_1, "익일최종거래일에의한 상장폐지종목", xls_path, 4, 0);
    $c.data.downloadGridViewOffice(grd_ELW_List_2, "금일행사종료일1개월전 상장폐지예고종목", xls_path, 36, 0);
    $c.data.downloadGridViewOffice(grd_ELW_List_3, "금일전부보유1개월로 인한 상장폐지 우려종목", xls_path, 36, 0);
    $c.data.downloadGridViewOffice(grd_ELW_List_4, "기초자산미등록회사", xls_path, 32, 0);
};
