scwin.gform_onload = function() {
    if (js_market == "1" || js_market == "2") {
        $c.cm.setColumnProp(grd_List_1, "TR_MKT_NM", "Show", false);
        $c.cm.setColumnProp(grd_List_1, "ITEM_NM", "Width", $c.cm.getColumnProp(grd_List_1, "TR_MKT_NM", "Width") + $c.cm.getColumnProp(grd_List_1, "ITEM_NM", "Width"));
        if (js_market == "2") {
            MaxTab_01.setDisabled(true);
        } else {
            MaxTab_01.setDisabled(false);
        }
    }
    if (js_dep_cd == '2540') {
        //심사2팀
        MaxTab_01.setSelectedTabIndex(2);
    } else {
        MaxTab_01.setSelectedTabIndex(1);
    }

    //	PanelToGroupBox_01(panel_1);
    //	PanelToGroupBox_01(panel_5);
    scwin.fn_set_Init();
    scwin.fn_list_sync();
};
